        client,
        spaceId,
        sourceLocalId: nodeId,
        fname: link,
        sourcePath: attachment.path,
        mimetype,
        created: new Date(attachment.stat.ctime),
        lastModified: new Date(attachment.stat.mtime),
        content,
      });
    }
